    iron_celestialglobe = { name = "Železni nebesna krogla", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni nebesna krogla za astronome." },
    bronze_celestialglobe = { name = "Bronast nebesna krogla", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast nebesna krogla za astronome." },
    silver_celestialglobe = { name = "Srebrn nebesna krogla", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn nebesna krogla za astronome." },
    gilded_celestialglobe = { name = "Pozlačen nebesna krogla", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen nebesna krogla za astronome." },
    jewel_set_celestialglobe = { name = "Draguljast nebesna krogla", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast nebesna krogla za astronome." },
    royal_sovereign_celestialglobe = { name = "Kraljevski suveren nebesna krogla", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren nebesna krogla z biseri za krono." },
}
