    master_celestialglobe_atelier = { name = "Mojstrski celestialglobe atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_celestialglobe_palace = { name = "Suverena celestialglobe palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
CelestialGlobeMaker.ironStock = 14; CelestialGlobeMaker.bronzeStock = 12; CelestialGlobeMaker.woodStock = 14; CelestialGlobeMaker.leatherStock = 10; CelestialGlobeMaker.silverStock = 8; CelestialGlobeMaker.goldStock = 6; CelestialGlobeMaker.jewelStock = 4; CelestialGlobeMaker.pearlStock = 4
CelestialGlobeMaker.productStock = {}; CelestialGlobeMaker.buildings = {}; CelestialGlobeMaker.maker = nil; CelestialGlobeMaker.activeMaking = {}; CelestialGlobeMaker.totalProducts = 0; CelestialGlobeMaker.dayTimer = 0
function CelestialGlobeMaker.init() CelestialGlobeMaker.ironStock=14; CelestialGlobeMaker.bronzeStock=12; CelestialGlobeMaker.woodStock=14; CelestialGlobeMaker.leatherStock=10; CelestialGlobeMaker.silverStock=8; CelestialGlobeMaker.goldStock=6; CelestialGlobeMaker.jewelStock=4; CelestialGlobeMaker.pearlStock=4; CelestialGlobeMaker.productStock={}; CelestialGlobeMaker.buildings={}; CelestialGlobeMaker.maker=nil; CelestialGlobeMaker.activeMaking={}; CelestialGlobeMaker.totalProducts=0; CelestialGlobeMaker.dayTimer=0; print("[CelestialGlobeMaker] Royal Celestial Globe Maker System initialized (6 products, 4 buildings)") end
function CelestialGlobeMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CelestialGlobeMaker.maker={name=n or ("Kroglasti "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kroglasti najet: %s (spretnost: %d)",CelestialGlobeMaker.maker.name,s),"success") end; return true end
function CelestialGlobeMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CelestialGlobeMaker.build(id) local ok,e=CelestialGlobeMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CelestialGlobeMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CelestialGlobeMaker.getQualityBonus() local b=0; for _,bd in ipairs(CelestialGlobeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CelestialGlobeMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and CelestialGlobeMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and CelestialGlobeMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and CelestialGlobeMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and CelestialGlobeMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and CelestialGlobeMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CelestialGlobeMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CelestialGlobeMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CelestialGlobeMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CelestialGlobeMaker.buildings==0 then return false,"Potrebna krogelna delavnica" end; if not CelestialGlobeMaker.maker then return false,"Potreben kroglasti" end; return true end
function CelestialGlobeMaker.make(pt,qty) qty=qty or 1; local ok,e=CelestialGlobeMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then CelestialGlobeMaker.ironStock=CelestialGlobeMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then CelestialGlobeMaker.bronzeStock=CelestialGlobeMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then CelestialGlobeMaker.woodStock=CelestialGlobeMaker.woodStock-d.woodCost*qty end; if d.leatherCost then CelestialGlobeMaker.leatherStock=CelestialGlobeMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then CelestialGlobeMaker.silverStock=CelestialGlobeMaker.silverStock-d.silverCost*qty end; if d.goldCost then CelestialGlobeMaker.goldStock=CelestialGlobeMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CelestialGlobeMaker.jewelStock=CelestialGlobeMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CelestialGlobeMaker.pearlStock=CelestialGlobeMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CelestialGlobeMaker.maker then t=math.max(1,t-math.floor(CelestialGlobeMaker.maker.skill/13)) end; table.insert(CelestialGlobeMaker.activeMaking,{id="celestialglobe_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CelestialGlobeMaker.completeMaking(m) local q=1.0+(CelestialGlobeMaker.getQualityBonus()/100); if CelestialGlobeMaker.maker then q=q+(CelestialGlobeMaker.maker.skill/140) end; q=math.min(2.5,q); CelestialGlobeMaker.productStock[m.productType]=(CelestialGlobeMaker.productStock[m.productType] or 0)+m.quantity; CelestialGlobeMaker.totalProducts=CelestialGlobeMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CelestialGlobeMaker.maker then CelestialGlobeMaker.maker.itemsMade=CelestialGlobeMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CelestialGlobeMaker.maker.skill=math.min(100,CelestialGlobeMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Krogla izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"celestialglobe.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CelestialGlobeMaker.update(dt) if not _G.state then return end; CelestialGlobeMaker.dayTimer=CelestialGlobeMaker.dayTimer+dt; if CelestialGlobeMaker.dayTimer>=30 then CelestialGlobeMaker.dayTimer=0; for i=#CelestialGlobeMaker.activeMaking,1,-1 do local m=CelestialGlobeMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CelestialGlobeMaker.completeMaking(m); table.remove(CelestialGlobeMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CelestialGlobeMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CelestialGlobeMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CelestialGlobeMaker.getStats() return {ironStock=CelestialGlobeMaker.ironStock,bronzeStock=CelestialGlobeMaker.bronzeStock,woodStock=CelestialGlobeMaker.woodStock,leatherStock=CelestialGlobeMaker.leatherStock,silverStock=CelestialGlobeMaker.silverStock,goldStock=CelestialGlobeMaker.goldStock,jewelStock=CelestialGlobeMaker.jewelStock,pearlStock=CelestialGlobeMaker.pearlStock,productStock=CelestialGlobeMaker.productStock,numBuildings=#CelestialGlobeMaker.buildings,hasMaker=CelestialGlobeMaker.maker~=nil,makerName=CelestialGlobeMaker.maker and CelestialGlobeMaker.maker.name or "—",makerSkill=CelestialGlobeMaker.maker and CelestialGlobeMaker.maker.skill or 0,activeMaking=#CelestialGlobeMaker.activeMaking,totalProducts=CelestialGlobeMaker.totalProducts} end
return CelestialGlobeMaker
